<?php  namespace QASI\modules\tencent_cos; use qqworld_collector\lib\options; use qcloudcos\Cosapi as Cosapi; use Qcloud_cos\Cosapi as Cosapi_old; class tencent_cos extends \qqworld_collector_common { var $allowed_image_types = array('image/jpeg', 'image/gif', 'image/png'); var $authorities; var $slug = 'tencent_cos'; var $optimize; var $tencent_cos; var $app_id; var $secretID; var $secretKey; var $bucket; var $sync_delete; var $auto_replace; var $accessed = false; var $optimize_url; var $optimize_protocol; var $optimize_host; var $optimize_folder; public function __construct() { $this->options = new options; $this->authorities = array( 'private' => 'Private', 'public-read-write' => 'Public Read Write', 'public-read' => 'Public Read' ); $this->optimize = get_option('qqworld-auto-save-images-optimize', array('enabled' => 'no', 'mode' => 'local')); $this->tencent_cos = get_option('qqworld-auto-save-images-tencent-cos', array('sync-delete' => 'yes', 'auto-replace' => 'yes')); $this->edition = isset($this->tencent_cos['edition']) ? $this->tencent_cos['edition'] : 'old'; $this->timeout = isset($this->tencent_cos['timeout']) ? $this->tencent_cos['timeout'] : 1800; $this->region = isset($this->tencent_cos['region']) ? $this->tencent_cos['region'] : 'gz'; $this->app_id = isset($this->tencent_cos['app-id']) ? $this->tencent_cos['app-id'] : ''; $this->secretID = isset($this->tencent_cos['secretID']) ? $this->tencent_cos['secretID'] : ''; $this->secretKey = isset($this->tencent_cos['secretKey']) ? $this->tencent_cos['secretKey'] : ''; $this->bucket = isset($this->tencent_cos['bucket']) ? $this->tencent_cos['bucket'] : ''; $this->sync_delete = isset($this->tencent_cos['sync-delete']) ? $this->tencent_cos['sync-delete'] : 'no'; $this->auto_replace = isset($this->tencent_cos['auto-replace']) ? $this->tencent_cos['auto-replace'] : 'no'; $this->delete_attachment_after_synced = isset($this->tencent_cos['delete-attachment-after-synced']) ? $this->tencent_cos['delete-attachment-after-