('/(https?:)?\/\/'.$home_url['host'].'\//i', '', $url); $source_path = $basedir . '/' . $destination_path; if (file_exists($source_path)) { if ($this->upload_by_file($destination_path, $source_path)) $synced_resources[] = $url; } } $synced_resources = array_flip(array_flip($synced_resources)); update_option('synced_resources', $synced_resources); } } if ($synced_resources) { foreach ($synced_resources as $resource) { $replacement = preg_replace('/(https?:)?\/\/'.$home_url['host'].'/i', $this->protocol . $this->host, $resource); $buffer = str_replace( $resource, $replacement, $buffer ); } } return $buffer; } public function sync_file() { if (!isset($_POST['file'])) echo json_encode(array( 'error' => 1, 'msg' => __('File path can not be empty.', $this->text_domain) )); $file = $_POST['file']; $wp_upload_dir = wp_upload_dir(); $basedir = str_replace('/wp-content/uploads', '', $wp_upload_dir['basedir']); if ( $this->app_id && $this->secretID && $this->secretKey && $this->bucket) { switch ($this->edition) { case 'old': $listRet = Cosapi_old::listFolder($this->bucket, "/"); break; case 'new': $listRet = Cosapi::listFolder($this->bucket, "/"); break; case 'v5': break; } } $destination_path = $file; $source_path = $basedir . $file; if (file_exists($source_path)) { $this->upload_by_file($destination_path, $source_path); echo json_encode(array( 'error' => 0, 'msg' => sprintf(__('File has been synchronized: %s.', $this->text_domain), $source_path) )); } else { echo json_encode(array( 'error' => 1, 'msg' => sprintf(__('File is not exists: %s.', $this->text_domain), $source_path) )); } exit; } public function optimize_action() { add_filter( 'image_send_to_editor',array($this, 'image_send_to_editor'), 10, 8 ); add_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); add_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); add_action( 'delete_attachment', array($this, 'delete_attachment') ); add_action( 'qqworld-auto-save-images-after-sync-oss-'.$this->slug, array($this, 'do_delete_attachment_after_synced') ); add_filter( 'wp_calculate_image_srcset', array($this, 'wp_calculate_image_srcset'), 10, 5); } public function wp_calculate_image_srcset($sources, $size_array, $image_src, $image_meta, $attachment_id) { $is_synced = get_post_meta($attachment_id, '_sync_tencent_cos', true); if ($is_synced) { foreach ($sources as $id => $source) { $sources[$id]['url'] = $this->parse_url($sources[$id]['url'], $this->tencent_cos); } } return $sources; } public function get_attachments_list() { if (!current_user_can($this->options->authorization)) return; $mode = $_REQUEST['mode']; $paged = $_REQUEST['paged']; switch ($mode) { case 'fast': $args = array( 'post_type' => 'attachment', 'meta_key' => '_sync_tencent_cos', 'meta_value' => 1, 'meta_compare' => 'NOT EXISTS', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; case 'smart': $args = array( 'post_type' => 'attachment', 'posts_per_page' => 1000, 'offset' => 1000*$paged ); break; } $attachments = get_posts($args); if (!empty($attachments)) { switch ($mode) { case 'fast': $success_message = sprintf(_n('%d no synced attachment found, syncing...', '%d no synced attachments found, syncing...', count($attachments), $this->text_domain), number_format_i18n(count($attachments))); break; case 'smart': $success_message = sprintf(_n('%d attachment found, scanning...', '%d attachments found, scanning...', count($attachments), $this->text_domain), number_format_i18n(count($attachments))); break; } $array = array(); foreach ($attachments as $attachment) $array[] = $attachment->ID; $results = array( 'success' => 1, 'msg' => $success_message, 'attachments' => $array ); } else { $failed_message = __('Congratulations, seems like all attachments had already synced.', $this->text_domain); $results = array( 'success' => 0, 'msg' => $failed_message ); } echo json_encode($results); exit; } public function exclude_domain($exclude_domain) { if (!is_array($exclude_domain)) $exclud