e['mode'] == $this->slug && $this->app_id && $this->secretID && $this->secretKey && $this->bucket) { switch ($this->edition) { case 'old': $listRet = Cosapi_old::listFolder($this->bucket, "/"); if ($listRet['code'] === 0) $this->accessed = true; break; case 'new': $listRet = Cosapi::listFolder($this->bucket, "/"); if ($listRet['code'] === 0) $this->accessed = true; break; case 'v5': try { $result = $this->cosClient->listObjects(array( 'Bucket' => $this->bucket )); $this->accessed = true; } catch (\Exception $e) { } break; } } $metadata = wp_get_attachment_metadata( $post_id ); $sizes = $this->parse_metadata($post_id, $metadata, $this->tencent_cos); if (!empty($sizes)) foreach ($sizes as $size) { if ($this->is_object_exist($size['destination_path'])) $this->delete_object($size['destination_path']); } } } public function do_delete_attachment_after_synced($res) { $attachment_id = $res['id']; $is_synced = get_post_meta($attachment_id, '_sync_tencent_cos', true); if ($this->delete_attachment_after_synced == 'yes' && $is_synced == 1) { wp_schedule_single_event( time() + 10, 'cron_delete_attachment_after_synced', array($attachment_id) ); } } public function wp_get_attachment_url($url, $post_id) { if ( get_post_meta($post_id, '_sync_tencent_cos', true) ) $url = $this->parse_url($url, $this->tencent_cos); return $url; } public function image_send_to_editor($html, $id, $caption, $title, $align, $url, $size, $alt) { if (get_post_meta($id, '_sync_tencent_cos', true)) { remove_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); remove_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); $original_image_url = wp_get_attachment_image_src($id, 'full'); add_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); add_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); $synced_image_url = wp_get_attachment_image_src($id, 'full'); $html = str_replace($original_image_url[0], $synced_image_url[0], $html); } return $html; } public function image_downsize($downsize, $id, $size) { if (get_post_meta($id, '_sync_tencent_cos', true)) { $metadata = wp_get_attachment_metadata( $id ); $sizes = $this->parse_metadata($id, $metadata, $this->tencent_cos); $image_sizes = !empty($metadata['sizes']) ? $metadata['sizes'] : null; if ( !is_array($size) ) { if (!isset($sizes[$size])) return null; $width = isset($sizes[$size]['width']) ? $sizes[$size]['width'] : ''; $height = isset($sizes[$size]['height']) ? $sizes[$size]['height'] : ''; return $size == 'full' ? array($sizes[$size]['src'], $width, $height) : array($sizes[$size]['src'], $width, $height, true); } else { if ( $intermediate = image_get_intermediate_size($id, $size) ) { $width = $intermediate['width']; $height = $intermediate['height']; foreach ($image_sizes as $size_name => $size) { if ($width < $size['width'] && $height < $size['height']) { break; } } return $size_name == 'full' ? array($sizes[$size_name]['src'], $width, $height) : array($sizes[$size_name]['src'], $width, $height, true); } else if (isset($sizes['full'])) { return array($sizes['full']['src'], $size[0], $size[1]); } } } } public function auto_replace($attachment_id, $type, $args=null) { if ($this->auto_replace != 'yes') return; global $wpdb; remove_filter( 'wp_get_attachment_url', array($this, 'wp_get_attachment_url'), 10, 2 ); remove_filter( 'image_downsize', array($this, 'image_downsize'), 10, 3 ); $metadata = wp_get_attachment_metadata( $attachment_id ); $queues = array(); if (in_array($type, $this->allowed_image_types)) { $sizes = $this->parse_metadata($attachment_id, $metadata, $this->tencent_cos); if (!empty($sizes)) foreach ($sizes as $name => $size) { $queues[$name] = array(); $original_url = wp_get_attachment_image_src($attachment_id, $name); $queues[$name]['source_url'] = $original_url[0]; $queues[$name]['destination_url'] = $size['src']; } } else { $attachment_url = wp_get_attachment_url($attachment_id); $queues['file'] = array( 'source_url' => $at