; $attachment_id = $_POST['attachment_id']; $this->sync($attachment_id, null, null, $mode); $results = array( 'msg' => __('Synced', $this->text_domain) ); echo json_encode($results); exit; } public function sync_single_tencent_cos($attachment_id=null) { if ( !current_user_can( $this->options->authorization ) ) return; $mode = isset($_POST['mode']) ? $_POST['mode'] : 'fast'; $attachment_id = $attachment_id ? $attachment_id : $_POST['attachment_id']; $results = $this->sync($attachment_id, null, null, $mode); echo json_encode($results); exit; } public function sync($attachment_id, $attachment=null, $metadata=null, $mode='fast') { if ( isset($this->optimize['enabled']) && $this->optimize['enabled'] == 'yes' && $this->optimize['mode'] == $this->slug && $this->app_id && $this->secretID && $this->secretKey && $this->bucket) { switch ($this->edition) { case 'old': $listRet = Cosapi_old::listFolder($this->bucket, "/"); if ($listRet['code'] === 0) $this->accessed = true; break; case 'new': $listRet = Cosapi::listFolder($this->bucket, "/"); if ($listRet['code'] === 0) $this->accessed = true; break; case 'v5': try { $result = $this->cosClient->listObjects(array( 'Bucket' => $this->bucket )); $this->accessed = true; } catch (\Exception $e) { echo $e->getMessage(); } break; } } if ($attachment) { $type = is_object($attachment) ? $attachment->post_mime_type : $attachment['post_mime_type']; } else { $attachment = get_post($attachment_id); $type = $attachment->post_mime_type; } $metadata = $metadata ? $metadata : wp_get_attachment_metadata( $attachment_id ); $results = array( 'type' => $type, 'metadata' => $metadata, 'attachment' => $attachment ); $sizes = $this->parse_metadata($attachment_id, $metadata, $this->tencent_cos); if (in_array($type, $this->allowed_image_types)) { if (!empty($sizes)) foreach ($sizes as $label => $size) { $destination_path = $size['destination_path']; $source_path = $size['source_path']; $allow = false; switch ($mode) { case 'fast': if (file_exists($source_path)) $allow = true; break; case 'smart': $result = $this->is_object_exist($destination_path); if (!$result) $allow = true; break; } if ($allow) $this->upload_by_file($destination_path, $source_path); else unset($sizes[$label]); } $results['sizes'] = $sizes; $this->auto_replace($attachment_id, $type, $sizes); } else { if (isset($sizes['file'])) { $destination_path = $sizes['file']['destination_path']; $source_path = $sizes['file']['source_path']; if (file_exists($source_path)) { $this->upload_by_file($destination_path, $source_path); $this->auto_replace($attachment_id, $type, $source_path); } } } $results['success'] = 1; update_post_meta($attachment_id, '_sync_tencent_cos', 1); return $results; } public function parse_url($url, $optimize_url) { $protocol = $optimize_url['protocol']; $host = $optimize_url['host']; $folder = $optimize_url['folder']; $url = preg_match('/uploads(.*?)$/i', $url, $match); $url = $protocol . $host . $folder . $match[1]; return $url; } public function parse_filepath($file, $optimize_url) { $protocol = $optimize_url['protocol']; $host = $optimize_url['host']; $folder = $optimize_url['folder']; $file_path = preg_match('/uploads(.*?)$/i', $file, $match); if ($file_path) { return array( 'icon' => site_url('/wp-includes/images/media/document.png'), 'src' => $protocol . $host . $folder . $match[1], 'destination_path' => $folder . $match[1], 'source_path' => $file, ); } else return null; } public function parse_metadata($attachment_id, $metadata, $optimize_url) { $dirs = wp_upload_dir(); $path = $dirs['path']; $sizes = array(); if (isset($metadata['file'])) { $full_file = $metadata['file']; $subpath = explode('/', $full_file); array_pop($subpath); $folder_path = implode('/', $subpath); $protocol = $optimize_url['protocol']; $host = $optimize_url['host']; $folder = $optimize_url['folder']; $folder = preg_replace('/^\//', '', $folder); $folder = $folder ? $folder . '/' : ''; $subfolder = $folder . $folder_path; $dir = $dirs['path'] . DIRECTORY_SEPARATOR; $sizes['full'] = array( 'src' => $protocol . $host . '/' . $folder . $full_file, 'destination_path' => $folder . $full_file, 'source_path' => $dirs['basedir'] . DIRECTORY_SEPARATOR . $metadata['file'], 'width' => $metadata['width'], 'height' => $metadata['height'] ); if (!empty($metadata['sizes'])) foreach ($metadata['sizes'] as $label => $size) { $sizes[$label] = array( 'src' => $protocol . $host . '/' . $subfolder . '/' . $size['file'], 'destination_path' => $subfolder . '/' . $size['file'], 'source_path' => $dirs['basedir'] . '/' . $folder_path . '/' . $size['file'], 'width' => $size['width'], 'height' => $size['height'] ); } } else { $file = get_attached_file($attachment_id); $result = $this->parse_filepath($file, $this->tencent_cos); if (!empty($result)) { $destination_path = $result['destination_path']; $source_path = $result['source_path']; $sizes['file'] = array( 'destination_path' => $destination_path, 'source_path' => $source_path ); $sizes['file'] = $result; } }; return $sizes; } public function sync_tencent_cos($metadata, $attachment_id, $optimize_url) { $this->sync($attachment_id, null, $metadata); } public function languages() { __('Private', $this->text_domain); __('Public Read Write', $this->text_domain); __('Public Read', $this->text_domain); } public function includes() { switch ($this->edition) { case 'old': require_once QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY_SEPARATOR . 'tencent_cos_sdk' . DIRECTORY_SEPARATOR . 'include_old.php'; break; case 'new': require_once QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY_SEPARATOR . 'tencent_cos_sdk' . DIRECTORY_SEPARATOR . 'include.php'; Cosapi::setTimeout($this->timeout); Cosapi::setRegion($this->region); break; case 'v5': require_once QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY_SEPARATOR . 'tencent_cos_sdk' . DIRECTORY_SEPARATOR . 'v5' . DIRECTORY_SEPARATOR . 'cos-autoloader.php'; $this->cosClient = new \Qcloud\Cos\Client(array( 'region' => $this->region, 'credentials'=> array( 'appId' => $this->app_id,