rRet = array( 'code' => 0 ); break; } if ($createFolderRet['code'] !== 0) $success = false; } } return $success; } public function is_dir_exist($dir) { switch ($this->edition) { case 'old': $statRet = Cosapi_old::statFolder($this->bucket, $dir); break; case 'new': $statRet = Cosapi::statFolder($this->bucket, $dir); break; case 'v5': $statRet = array( 'code' => 0 ); break; } return $statRet['code'] === 0; } public function is_object_exist($destination_path) { switch ($this->edition) { case 'old': $statRet = Cosapi_old::stat($this->bucket, $destination_path); break; case 'new': $statRet = Cosapi::stat($this->bucket, $destination_path); break; case 'v5': try { $result = $this->cosClient->getObject(array( 'Bucket' => $this->bucket, 'Key' => $destination_path, )); $statRet = array( 'code' => 0 ); } catch (\Exception $e) { $statRet = array( 'code' => 1, 'message' => $e->getMessage() ); } break; } return $statRet['code'] === 0; } public function upload_by_file($destination_path, $source_path) { set_time_limit(3600); $dir = dirname($destination_path); if ($this->is_dir_exist($dir)) $dir_created = true; else $dir_created = $this->create_directory($dir); if ($dir_created) { if ($this->is_object_exist($destination_path)) $this->delete_object($destination_path); if (!preg_match('/^\//', $destination_path, $match)) $destination_path = '/'.$destination_path; switch ($this->edition) { case 'old': $uploadRet = Cosapi_old::upload($source_path, $this->bucket, $destination_path); break; case 'new': $uploadRet = Cosapi::upload($this->bucket, $source_path, $destination_path); break; case 'v5': try { $body = file_get_contents($source_path); $result = $this->cosClient->upload($this->bucket, $destination_path, $body); $uploadRet = array( 'code' => 0 ); } catch (\Exception $e) { $uploadRet = array( 'code' => 0, 'message' => $e->getMessage() ); } break; } return $uploadRet['code'] === 0; } return false; } public function delete_object($object) { switch ($this->edition) { case 'old': $delRet 